*** Settings ***
Library    Collections

*** Test Cases ***
Build Ship Inventory
    @{inventory}=    Create List
    &{c1}=    Create Dictionary    name=Navigation    type=Navigation    status=Online    priority=1
    &{c2}=    Create Dictionary    name=Power Core    type=Power    status=Online    priority=1
    &{c3}=    Create Dictionary    name=Backup Power    type=Power    status=Offline    priority=3
    &{c4}=    Create Dictionary    name=Main Engine    type=Propulsion    status=Online    priority=1
    &{c5}=    Create Dictionary    name=Life Support    type=Life Support    status=Online    priority=1
    &{c6}=    Create Dictionary    name=Sensors    type=Sensors    status=Offline    priority=2
    Append To List    ${inventory}    ${c1}    ${c2}    ${c3}    ${c4}    ${c5}    ${c6}
    ${total}=    Get Length    ${inventory}
    Log    Total components: ${total}
    Should Be Equal As Integers    ${total}    6
    Set Suite Variable    @{INVENTORY}    @{inventory}

Find Critical Components
    @{critical}=    Create List
    FOR    ${component}    IN    @{INVENTORY}
        ${priority}=    Get From Dictionary    ${component}    priority
        IF    ${priority} == 1
            Append To List    ${critical}    ${component}
        END
    END
    ${count}=    Get Length    ${critical}
    Log    Critical components: ${count}
    Should Be Equal As Integers    ${count}    4

Find Offline Systems
    @{offline}=    Create List
    FOR    ${component}    IN    @{INVENTORY}
        ${status}=    Get From Dictionary    ${component}    status
        IF    '${status}' == 'Offline'
            ${name}=    Get From Dictionary    ${component}    name
            Append To List    ${offline}    ${name}
        END
    END
    Log Many    @{offline}
    ${count}=    Get Length    ${offline}
    Should Be Equal As Integers    ${count}    2
    List Should Contain Value    ${offline}    Backup Power
    List Should Contain Value    ${offline}    Sensors

Inventory Summary
    ${total}=    Get Length    ${INVENTORY}
    ${online_count}=    Set Variable    0
    ${offline_count}=    Set Variable    0
    FOR    ${component}    IN    @{INVENTORY}
        ${status}=    Get From Dictionary    ${component}    status
        IF    '${status}' == 'Online'
            ${online_count}=    Set Variable    ${online_count + 1}
        ELSE
            ${offline_count}=    Set Variable    ${offline_count + 1}
        END
    END
    Log    === INVENTORY SUMMARY ===
    Log    Total Components: ${total}
    Log    Online: ${online_count}
    Log    Offline: ${offline_count}
    Should Be Equal As Integers    ${online_count}    4
    Should Be Equal As Integers    ${offline_count}    2
